export function registerLiberationFonts(doc: any) {
  doc.addFileToVFS("LiberationSans-Regular.woff2", liberationSansRegularBase64);
  doc.addFont("LiberationSans-Regular.woff2", "LiberationSans", "normal");
  doc.addFileToVFS("LiberationSans-Bold.woff2", liberationSansBoldBase64);
  doc.addFont("LiberationSans-Bold.woff2", "LiberationSans", "bold");
  doc.setFont("LiberationSans");
}
